use xiom.io;

enum Alert {
  Normal,
  Hot(temp: Int),
  Cold(temp: Int),
  Extreme(temp: Int),
}

fn check_temperature(celsius: Int) -> Alert {
  if celsius >= 40 { return Alert.Extreme(celsius); }
  if celsius >= 30 { return Alert.Hot(celsius); }
  if celsius <= 0 { return Alert.Cold(celsius); }
  return Alert.Normal;
}

fn Alert.message(self) -> Str {
  match self {
    Normal => { return "Temperature is comfortable."; }
    Hot(temp) => { return "Warning: " + temp + "C is hot!"; }
    Cold(temp) => { return "Warning: " + temp + "C is cold!"; }
    Extreme(temp) => { return "DANGER: " + temp + "C is extreme!"; }
  }
}

fn main() -> Int {
  let alert = check_temperature(35);
  match alert {
    Hot(temp) => { return temp; }
    _ => { return 0; }
  }
}
